<include file="Publics:header"/>	<div class="mainbox">		<div style="margin-bottom: 15px;background-color: #eef3f7;padding: 10px;">			1、首页只展示排序值最大的{pigcms{$title},(优先级：排序 > 添加时间)<br/>			2、<if condition="$_GET['grid_num'] eq 4">活动商品低于四个则不在首页展示，</if>最多展示最新的<if condition="$_GET['grid_num'] eq 4">8<else/>3</if>件商品<br/>			<p> 3、总平台设置的宫格不允许操作</p>		</div>		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Adver/grid_num_list',$_GET)}" class="on">{pigcms{$title} - 列表</a>|				<if condition="(($assign_type['type_8'] && $_GET['grid_num'] eq 4) || ($assign_type['type_9'] && $_GET['grid_num'] eq 3)) || $_GET['source'] eq sys">				<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Adver/grid_num_add',array('grid_num'=>$_GET['grid_num'],'source'=>$_GET['source']))}','添加{pigcms{$_GET['grid_num']}宫格推荐广告',850,440,true,false,false,addbtn,'add',true);">添加宫格广告位</a>				</if>			</ul>		</div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>活动标题</th>							<th>活动类型</th>							<th>开始时间</th>							<th>结束时间</th>							<if condition="(($assign_type['type_8'] && $_GET['grid_num'] eq 4) || ($assign_type['type_9'] && $_GET['grid_num'] eq 3)) || $_GET['source'] eq sys">							<th>关联商品</th>							</if>							<th style="width: 60px">排序</th>							<if condition="(($assign_type['type_8'] && $_GET['grid_num'] eq 4) || ($assign_type['type_9'] && $_GET['grid_num'] eq 3)) || $_GET['source'] eq sys">							<th class="textcenter">操作</th>							</if>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.type}</td>									<td>{pigcms{$vo.start_time}</td>									<td>{pigcms{$vo.end_time}</td>									<if condition="(($assign_type['type_8'] && $_GET['grid_num'] eq 4) || ($assign_type['type_9'] && $_GET['grid_num'] eq 3)) || $_GET['source'] eq sys">									<td>										<if condition="$vo.village_id gt 0 || $_GET['source'] eq sys">										<a href="javascript:void(0);" class="related_goods" onclick="window.top.artiframe('{pigcms{:U('Adver/grid_num_add_goods',array('id'=>$vo['id']))}','添加{pigcms{$_GET['grid_num']}宫格推荐广告商品',1100,700,true,false,false,false,'add',true);">关联商品</a>										</if>									</td>									</if>									<td>{pigcms{$vo.sort}</td>									<if condition="(($assign_type['type_8'] && $_GET['grid_num'] eq 4) || ($assign_type['type_9'] && $_GET['grid_num'] eq 3)) || $_GET['source'] eq sys">									<td class="textcenter">										<if condition="$vo.village_id gt 0 || $_GET['source'] eq sys">										<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Adver/grid_num_edit',array('id'=>$vo['id']))}','编辑广告信息',850,520,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Adver/grid_num_del')}">删除</a>										</if>									</td>									</if>								</tr>							</volist>						<else/>							<tr><td class="textcenter red" colspan="7" >列表为空！</td></tr>						</if>					</tbody>				</table>				{pigcms{$result.pagebar}			</div>		</form>	</div><style>	.related_goods {			margin: 10px 0;			padding: 10px 20px;			border: 1px dashed #CCCCCC;			background-color: #ffffff;      display: inline-block;	}  .table-list .summary {      margin: 10px 25px 5px 0 !important;      text-align: right !important;  }  .table-list .pager {      margin: 0 25px 5px 0 !important;      text-align: right !important;  }  .pager .next>a {      height: 30px;      line-height: 30px;  }  .pager .prev>a {      height: 30px;      line-height: 30px;  }</style><include file="Publics:footer"/>